create or replace function public.schoolpro_record_offline_payment(p_invoice uuid,p_amount numeric,p_method text,p_reference text,p_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$declare i public.schoolpro_invoices;pid uuid;begin select * into i from public.schoolpro_invoices where id=p_invoice for update;if i.id is null then raise exception 'Invoice not found';end if;if not(public.schoolpro_member_can_manage(i.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=i.school_id and m.user_id=auth.uid() and m.role::text in('accountant','bursar'))) then raise exception 'Not authorized';end if;if p_amount<=0 or coalesce(i.amount_paid,0)+p_amount>i.amount_due then raise exception 'Invalid payment amount';end if;insert into public.schoolpro_fee_payments(school_id,invoice_id,student_id,amount,method,reference,notes,recorded_by) values(i.school_id,i.id,i.student_id,p_amount,p_method,p_reference,p_notes,auth.uid()) returning id into pid;update public.schoolpro_invoices set amount_paid=coalesce(amount_paid,0)+p_amount,status=case when coalesce(amount_paid,0)+p_amount>=amount_due then 'paid'::public.schoolpro_invoice_status else 'part_paid'::public.schoolpro_invoice_status end,updated_at=now() where id=i.id;return pid;end$$;revoke all on function public.schoolpro_record_offline_payment(uuid,numeric,text,text,text) from public,anon;grant execute on function public.schoolpro_record_offline_payment(uuid,numeric,text,text,text) to authenticated;